#include <bits/stdc++.h>
using namespace std;

// Reverse the lowest `len` bits of x.
long long reverseBits(long long x, int len) {
    long long r = 0;
    for (int i = 0; i < len; i++) r = (r << 1) | ((x >> i) & 1);
    return r;
}

int main() {
    long long n;
    cin >> n;
    long long best = n; // 0 is itself a binary palindrome
    for (int bits = 1; bits < 32; bits++) {
        int half = (bits + 1) / 2, lowLen = bits / 2;
        long long low = 1LL << (half - 1), high = (1LL << half) - 1, prefix = n >> lowLen;
        auto clamp = [&](long long v) { return max(low, min(high, v)); };
        // Nearest palindromes of this length come from the prefix of n, its neighbours, or the range ends.
        for (long long first : {low, high, clamp(prefix), clamp(prefix - 1), clamp(prefix + 1)}) {
            long long candidate = (first << lowLen) | reverseBits(first >> (bits % 2), lowLen);
            best = min(best, llabs(candidate - n));
        }
    }
    cout << best << "\n";
}

import java.util.*;

public class Main {
    // Reverse the lowest `len` bits of x.
    static long reverseBits(long x, int len) {
        long r = 0;
        for (int i = 0; i < len; i++) r = (r << 1) | ((x >> i) & 1);
        return r;
    }

    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        long best = n; // 0 is itself a binary palindrome
        for (int bits = 1; bits < 32; bits++) {
            int half = (bits + 1) / 2, lowLen = bits / 2;
            long low = 1L << (half - 1), high = (1L << half) - 1, prefix = n >> lowLen;
            // Nearest palindromes of this length come from the prefix of n, its neighbours, or the range ends.
            long[] firsts = {low, high, Math.max(low, Math.min(high, prefix)),
                Math.max(low, Math.min(high, prefix - 1)), Math.max(low, Math.min(high, prefix + 1))};
            for (long first : firsts) {
                long candidate = (first << lowLen) | reverseBits(first >> (bits % 2), lowLen);
                best = Math.min(best, Math.abs(candidate - n));
            }
        }
        System.out.println(best);
    }
}

package main

import "fmt"

// reverseBits reverses the lowest length bits of x.
func reverseBits(x, length int) int {
	r := 0
	for i := 0; i < length; i++ {
		r = r<<1 | (x>>i)&1
	}
	return r
}

func main() {
	var n int
	fmt.Scan(&n)
	best := n // 0 is itself a binary palindrome
	for bits := 1; bits < 32; bits++ {
		half, lowLen := (bits+1)/2, bits/2
		low, high, prefix := 1<<(half-1), 1<<half-1, n>>lowLen
		clamp := func(v int) int { return max(low, min(high, v)) }
		// Nearest palindromes of this length come from the prefix of n, its neighbours, or the range ends.
		for _, first := range []int{low, high, clamp(prefix), clamp(prefix - 1), clamp(prefix + 1)} {
			candidate := first<<lowLen | reverseBits(first>>(bits%2), lowLen)
			diff := candidate - n
			if diff < 0 {
				diff = -diff
			}
			best = min(best, diff)
		}
	}
	fmt.Println(best)
}
